import { pathToFileURL } from 'url';

async function main() {
  const fileUrl = pathToFileURL('d:/tn-enforcement-system/tn-forest-monitoring/server/src/services/gee/GeeAuthService.ts').href;
  const { GeeAuthService } = await import(fileUrl);

  const authService = GeeAuthService.getInstance();
  const token = await authService.getAccessToken();
  const config = authService.getConfig();

  console.log('Project ID:', config.projectId);
  console.log('Token exists:', !!token);

  const imageId = 'COPERNICUS/S2_SR_HARMONIZED/20200109T051201_20200109T051844_T43PHM';
  const exportUrl = `https://earthengine.googleapis.com/v1alpha/projects/${config.projectId}/image:export`;

  const sathiyarPolygon = {
    type: 'Polygon',
    coordinates: [
      [
        [78.07470465117308, 10.118261747031166],
        [78.08672717223784, 10.111838408411883],
        [78.0939406848767, 10.11969852887474],
        [78.08904580130034, 10.123501743888568],
        [78.07977128505037, 10.1228256200689],
        [78.07521990207582, 10.12198046329112],
        [78.07470465117308, 10.118261747031166],
      ],
    ],
  };

  const payload = {
    description: `sathiyar_baseline_${Date.now()}`,
    expression: {
      values: {
        'raw_image': {
          functionInvocationValue: {
            functionName: 'Image.load',
            arguments: {
              id: { constantValue: imageId },
            },
          },
        },
        'geom': {
          constantValue: sathiyarPolygon,
        },
        'clipped': {
          functionInvocationValue: {
            functionName: 'image.clip',
            arguments: {
              image: { valueReference: 'raw_image' },
              geometry: { valueReference: 'geom' },
            },
          },
        },
      },
      result: 'clipped',
    },
    fileExportOptions: {
      fileFormat: 'GEO_TIFF',
      driveDestination: {
        folder: 'MonitoringExports',
        filenamePrefix: `sathiyar_baseline_${Date.now()}`,
      },
    },
  };

  const res = await fetch(exportUrl, {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${token}`,
      'Content-Type': 'application/json',
      'X-Goog-User-Project': config.projectId,
    },
    body: JSON.stringify(payload),
  });

  console.log('Export HTTP Status:', res.status, res.statusText);
  const bodyText = await res.text();
  console.log('Export Response:', bodyText);
}

main().catch(console.error);
